alter table public.booking_bundles add column if not exists pricing_mode text not null default 'per_person', add column if not exists serves_people integer;
alter table public.booking_bundle_items add column if not exists component_area text, add column if not exists selection_mode text not null default 'fixed', add column if not exists min_select integer not null default 0, add column if not exists max_select integer not null default 0, add column if not exists item_quantity integer not null default 1;
alter table public.booking_components drop constraint if exists booking_components_component_type_check;
alter table public.booking_components add constraint booking_components_component_type_check check (component_type = any(array['service','menu_item','buffet','buffet_option']));
alter table public.booking_bundles drop constraint if exists booking_bundles_pricing_mode_check;
alter table public.booking_bundles add constraint booking_bundles_pricing_mode_check check (pricing_mode in ('per_person','fixed_package'));
alter table public.booking_bundles drop constraint if exists booking_bundles_serves_people_check;
alter table public.booking_bundles add constraint booking_bundles_serves_people_check check (serves_people is null or serves_people > 0);
alter table public.booking_bundle_items drop constraint if exists booking_bundle_items_selection_mode_check;
alter table public.booking_bundle_items add constraint booking_bundle_items_selection_mode_check check (selection_mode in ('fixed','choose'));
alter table public.booking_bundle_items drop constraint if exists booking_bundle_items_min_select_check;
alter table public.booking_bundle_items add constraint booking_bundle_items_min_select_check check (min_select >= 0);
alter table public.booking_bundle_items drop constraint if exists booking_bundle_items_max_select_check;
alter table public.booking_bundle_items add constraint booking_bundle_items_max_select_check check (max_select >= min_select);
alter table public.booking_bundle_items drop constraint if exists booking_bundle_items_item_quantity_check;
alter table public.booking_bundle_items add constraint booking_bundle_items_item_quantity_check check (item_quantity > 0);
create index if not exists idx_booking_bundle_items_bundle_area on public.booking_bundle_items(bundle_id,component_area,sort_order);
update public.booking_bundles set pricing_mode='per_person',serves_people=null where name in ('Ordinary Buffet','Standard Buffet','Ethnic Buffet');
update public.booking_bundles set name='Buffet — 45,000 UGX',pricing_mode='per_person',serves_people=null,description='Starters, stew, extra sauce, grills, food, green vegetables and additions. Component choices are enforced below.' where name='Standard Buffet';
update public.booking_bundles set name='Muchomo Platter',pricing_mode='fixed_package',serves_people=4,price_per_person=55000,description='Fixed platter serving 4 people: 2 sausages, goat, liver, chicken, fish fingers, chapatti, chips and salads.' where name='Muchomo Platter (4 People)';
