create or replace function public.calculate_booking_component_price(p_component_type text,p_source_id uuid,p_quantity integer)
returns table(name_snapshot text,description_snapshot text,unit_price numeric,line_total numeric,price_on_request boolean,service_id uuid,menu_item_id uuid,reference_key text)
language plpgsql stable set search_path=public as $$ declare s public.services%rowtype;m public.menu_items%rowtype;b public.booking_bundles%rowtype;q integer; begin
if coalesce(p_quantity,0)<=0 then raise exception 'Quantity must be greater than zero'; end if;
if p_component_type='service' then select * into s from public.services where id=p_source_id and active=true;if not found then raise exception 'Service is unavailable';end if;q:=case when s.pricing_mode in('per_person','per_person_team') then p_quantity else 1 end;unit_price:=case when s.pricing_mode='per_person_team' and s.team_threshold is not null then case when q<s.team_threshold then coalesce(s.small_group_price,s.price,0) else coalesce(s.full_team_price,s.price,0) end else coalesce(s.price,0) end;name_snapshot:=s.name;description_snapshot:=s.description;price_on_request:=unit_price=0 and s.price is null;service_id:=s.id;menu_item_id:=null;reference_key:=null;line_total:=case when price_on_request then 0 else unit_price*q end;return next;
elsif p_component_type='menu_item' then select * into m from public.menu_items where id=p_source_id and in_stock=true;if not found then raise exception 'Menu item is unavailable';end if;name_snapshot:=m.name;description_snapshot:=m.description;unit_price:=coalesce(m.price,0);price_on_request:=coalesce(m.price_on_request,false) or unit_price=0;service_id:=null;menu_item_id:=m.id;reference_key:=null;line_total:=case when price_on_request then 0 else unit_price*p_quantity end;return next;
elsif p_component_type='buffet' then select * into b from public.booking_bundles where id=p_source_id and active=true;if not found then raise exception 'Buffet package is unavailable';end if;name_snapshot:=b.name;description_snapshot:=b.description;unit_price:=coalesce(b.price_per_person,0);price_on_request:=coalesce(b.price_on_request,false) or unit_price=0;service_id:=null;menu_item_id:=null;reference_key:=b.id::text;line_total:=case when price_on_request then 0 when b.pricing_mode='fixed_package' then unit_price*greatest(1,ceil(p_quantity::numeric/coalesce(b.serves_people,1))::integer) else unit_price*p_quantity end;return next;
else raise exception 'Unsupported booking component type';end if;end $$;

create or replace function public.submit_public_booking_v3(p_customer_name text,p_phone text,p_email text,p_booking_date date,p_start_time time,p_people integer,p_notes text,p_components jsonb)
returns jsonb language plpgsql security definer set search_path=public,private,pg_catalog,pg_temp as $$
declare v_customer_id uuid;v_booking_id uuid;v_primary_service uuid;v_service_category text;v_total numeric:=0;v_on_request boolean:=false;v_has_catering boolean:=false;c jsonb;r record;v_qty integer;v_bundle record;v_opt jsonb;v_count integer;v_fixed record;v_selected_ids uuid[];
begin
if coalesce(trim(p_customer_name),'')='' then raise exception 'Customer name is required';end if;if p_booking_date is null then raise exception 'Booking date is required';end if;if p_booking_date<current_date then raise exception 'Booking date cannot be in the past';end if;if p_people is null or p_people<1 then raise exception 'People must be at least 1';end if;if jsonb_typeof(coalesce(p_components,'[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_components,'[]'::jsonb))=0 then raise exception 'Select at least one service or booking item';end if;
select c.id into v_customer_id from public.customers c where c.phone=private.normalize_phone(p_phone) limit 1;if v_customer_id is null then insert into public.customers(name,phone,email) values(trim(p_customer_name),private.normalize_phone(p_phone),nullif(trim(p_email),'')) returning id into v_customer_id;else update public.customers set name=trim(p_customer_name),email=coalesce(nullif(trim(p_email),''),email) where id=v_customer_id;end if;
insert into public.bookings(customer_id,service_id,booking_date,start_time,people,source,status,payment_status,total,total_on_request,notes) values(v_customer_id,null,p_booking_date,p_start_time,p_people,'website','pending','unpaid',0,false,nullif(trim(p_notes),'')) returning id into v_booking_id;
for c in select value from jsonb_array_elements(p_components) loop
if lower(coalesce(c->>'type','')) not in('service','menu_item','buffet') then raise exception 'Unsupported booking component type';end if;v_qty:=greatest(1,coalesce((c->>'quantity')::integer,p_people));select * into r from public.calculate_booking_component_price(lower(c->>'type'),(c->>'id')::uuid,v_qty);
insert into public.booking_components(booking_id,component_type,service_id,menu_item_id,reference_key,name_snapshot,description_snapshot,unit_price,quantity,price_on_request,bundle_id) values(v_booking_id,lower(c->>'type'),r.service_id,r.menu_item_id,r.reference_key,r.name_snapshot,r.description_snapshot,r.unit_price,v_qty,r.price_on_request,case when lower(c->>'type')='buffet' then (c->>'id')::uuid else null end);
if v_primary_service is null and r.service_id is not null then v_primary_service:=r.service_id;end if;if lower(c->>'type') in('menu_item','buffet') then v_has_catering:=true;end if;v_total:=v_total+coalesce(r.line_total,0);v_on_request:=v_on_request or r.price_on_request;
if lower(c->>'type')='buffet' then
select * into v_bundle from public.booking_bundles where id=(c->>'id')::uuid and active=true;if not found then raise exception 'Buffet package is unavailable';end if;
select array_agg((x->>'id')::uuid) into v_selected_ids from jsonb_array_elements(coalesce(c->'options','[]'::jsonb)) x where x ? 'id';
for v_fixed in select * from public.booking_bundle_items where bundle_id=v_bundle.id and active=true and selection_mode='fixed' order by sort_order loop insert into public.booking_components(booking_id,component_type,reference_key,name_snapshot,description_snapshot,unit_price,quantity,price_on_request,bundle_id) values(v_booking_id,'buffet_option',v_fixed.id::text,v_fixed.name,v_fixed.description,0,v_fixed.item_quantity,false,v_bundle.id);end loop;
for v_fixed in select distinct component_area,min(min_select) min_select,max(max_select) max_select from public.booking_bundle_items where bundle_id=v_bundle.id and active=true and selection_mode='choose' group by component_area loop
select count(*) into v_count from public.booking_bundle_items bi where bi.bundle_id=v_bundle.id and bi.component_area=v_fixed.component_area and bi.active=true and bi.selection_mode='choose' and bi.id=any(coalesce(v_selected_ids,array[]::uuid[]));if v_count<v_fixed.min_select or v_count>v_fixed.max_select then raise exception '%: choose between % and % option(s)',v_fixed.component_area,v_fixed.min_select,v_fixed.max_select;end if;end loop;
for v_opt in select value from jsonb_array_elements(coalesce(c->'options','[]'::jsonb)) loop select * into v_fixed from public.booking_bundle_items where id=(v_opt->>'id')::uuid and bundle_id=v_bundle.id and active=true and selection_mode='choose';if not found then raise exception 'Invalid buffet option for %',v_bundle.name;end if;insert into public.booking_components(booking_id,component_type,reference_key,name_snapshot,description_snapshot,unit_price,quantity,price_on_request,bundle_id) values(v_booking_id,'buffet_option',v_fixed.id::text,v_fixed.name,v_fixed.description,0,v_fixed.item_quantity,false,v_bundle.id);end loop;
end if;end loop;
select lower(coalesce(category,'')) into v_service_category from public.services where id=v_primary_service;if v_service_category is null then raise exception 'A valid primary service is required';end if;if v_service_category not in('sports','swimming') and not v_has_catering then raise exception 'Catering is required for this booking type. Please select a buffet or menu item.';end if;update public.bookings set service_id=v_primary_service,total=v_total,total_on_request=v_on_request where id=v_booking_id;return jsonb_build_object('booking_id',v_booking_id,'customer_id',v_customer_id,'total',v_total,'total_on_request',v_on_request);end $$;